rule CobaltStrike_Generic {
  meta:
    description = "Detect generic CobaltStrike beacon"
    author = "SOC"
    reference = "https://attack.mitre.org/software/S0005/"
  strings:
    $a = { 4D 5A ?? ?? ?? 00 00 00 00 00 00 }
    // heuristic: packed .NET assembly
  condition:
    // original condition caused false positives
    // new condition: require unsigned or mismatched Authenticode certificate
    $a and (pe.is_exe == false) and (pe.authenticode == false)
}

